use std::fs
use std::strings

struct Bst {
    keys: Vec<int>,
    lefts: Vec<int>,
    rights: Vec<int>,
    root: int,
}

impl Bst {
    fn contains(self, x: int) -> bool {
        let mut cur = self.root
        while cur >= 0 {
            let k = self.keys[cur]
            if x == k { return true }
            if x < k { cur = self.lefts[cur] } else { cur = self.rights[cur] }
        }
        false
    }

    fn add(self, x: int) {
        self.keys.push(x)
        self.lefts.push(-1)
        self.rights.push(-1)
        let id: int = self.keys.len() as int - 1
        if self.root < 0 {
            self.root = id
            return
        }
        let mut cur = self.root
        loop {
            if x < self.keys[cur] {
                if self.lefts[cur] < 0 {
                    self.lefts[cur] = id
                    return
                }
                cur = self.lefts[cur]
            } else {
                if self.rights[cur] < 0 {
                    self.rights[cur] = id
                    return
                }
                cur = self.rights[cur]
            }
        }
    }

    fn remove(self, x: int, node: int) -> int {
        if node < 0 { return node }
        let k = self.keys[node]
        if x < k {
            self.lefts[node] = self.remove(x, self.lefts[node])
            return node
        }
        if x > k {
            self.rights[node] = self.remove(x, self.rights[node])
            return node
        }
        let l = self.lefts[node]
        let r = self.rights[node]
        if l < 0 { return r }
        if r < 0 { return l }
        let mut s = r
        while self.lefts[s] >= 0 { s = self.lefts[s] }
        let sk = self.keys[s]
        self.keys[node] = sk
        self.rights[node] = self.remove(sk, r)
        node
    }

    fn height(self, node: int) -> int {
        if node < 0 { return 0 }
        let a = self.height(self.lefts[node])
        let b = self.height(self.rights[node])
        if a > b { a + 1 } else { b + 1 }
    }

    fn walk(self, node: int, out: Vec<string>) {
        if node < 0 { return }
        self.walk(self.lefts[node], out)
        out.push("${self.keys[node]}")
        self.walk(self.rights[node], out)
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Bst { keys: [], lefts: [], rights: [], root: -1 }
    for line in text.lines() {
        let parts = strings::split_whitespace(line)
        if parts.len() == 0 { continue }
        let cmd = parts[0]
        if cmd == "insert" {
            let x = parts[1].parse::<int>().unwrap_or(0)
            if t.contains(x) { println("dup") } else { t.add(x); println("ok") }
        } else if cmd == "contains" {
            let x = parts[1].parse::<int>().unwrap_or(0)
            if t.contains(x) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let x = parts[1].parse::<int>().unwrap_or(0)
            if t.contains(x) {
                t.root = t.remove(x, t.root)
                println("ok")
            } else { println("missing") }
        } else if cmd == "inorder" {
            let mut out: Vec<string> = []
            t.walk(t.root, out)
            if out.len() == 0 { println("<empty>") } else { println(out.join(" ")) }
        } else if cmd == "height" {
            println("${t.height(t.root)}")
        } else if cmd == "min" {
            if t.root < 0 { println("empty") } else {
                let mut c = t.root
                while t.lefts[c] >= 0 { c = t.lefts[c] }
                println("${t.keys[c]}")
            }
        } else if cmd == "max" {
            if t.root < 0 { println("empty") } else {
                let mut c = t.root
                while t.rights[c] >= 0 { c = t.rights[c] }
                println("${t.keys[c]}")
            }
        }
    }
}

